html:
{#-
  LS Foods — Sales Invoice.

  Laid out like the client's old invoice ("LS Foods Spring 2026", 2026-10-22),
  re-arranged for a #10 window envelope:

      LS Foods                                          Invoice / Date / Order
      [ Bill To: name, billing address, phone ]  <- sits in the envelope window
                                                         Ship To (right)
      Project
      Delivery Location
      Product Code | Description | Quantity | Price | Item Total
      Order Notes (left)                     Free Dairy/Pizza, Subtotal,
                                             Delivery Charge, Total, Payment Applied,
                                             Total Amount Due, Credit Remaining (right)
      Payments: Check # | Date | Amount Paid | Applied to Invoice | Credit Remaining
      Thank-you line and the farm's address.

  The window block's position assumes the standard print margins (15 mm) and no
  Letter Head — the format carries its own header. Print with "Letter Head" off.

  FREE (the free dairy/pizza credit), Delivery Charge and Late Fee are order
  lines like any other, but print in the totals, as on the old invoice.

  Order Notes are driven by the items: any line in item group "Grains" adds the
  grain-storage note, SF5631 (pollock) adds the freezer-bag note.

  Beef / hog shares (share_billing.invoice_view) keep their build-sheet block:
      <share> (<weight> lbs.)                     <subtotal>
        Quarter Beef Deposit   4 x -600.00         -2,400.00
        <share>, hanging weight  370 lb x 6.50      2,405.00
        Processing Fee           370 lb x 0.90        333.00
        Balance due for this share                    338.00
  The deposit printed there is the share's Sales Order line (the fixed deposit);
  the money actually received is in Payment Applied and the payments table.

  A share of the order that is NOT on this invoice (Backorders & Invoicing
  invoices the other items first; the share follows on its own invoice once
  the hanging weight is known) prints in a "billed later" box with its
  deposit, and the deposit is held out of the credit: Total, Payment Applied,
  Total Amount Due, Beef / Hog Share Deposit (held), Credit Remaining.
-#}
{%- set view = invoice_view(doc) %}
{%- set t = namespace(free=0, delivery=0, late=0, has_free=0, has_late=0, grains=0, pollock=0) %}
{%- set products = [] %}
{%- for row in view.others %}
  {%- if row.item_code == "FREE" %}{% set t.free = t.free + row.amount %}{% set t.has_free = 1 %}
  {%- elif row.item_code == "Delivery Charge" %}{% set t.delivery = t.delivery + row.amount %}
  {%- elif row.item_code == "Late Fee" %}{% set t.late = t.late + row.amount %}{% set t.has_late = 1 %}
  {%- else %}{% set _ = products.append(row) %}{% endif %}
{%- endfor %}
{%- for row in doc.items %}
  {%- if row.item_group == "Grains" %}{% set t.grains = 1 %}{% endif %}
  {%- if row.item_code == "SF5631" %}{% set t.pollock = 1 %}{% endif %}
{%- endfor %}
{%- set subtotal = doc.net_total - t.delivery - t.late %}
{%- set order_total = doc.rounded_total or doc.grand_total %}
{#- Totals: Total - Payment Applied = Total Amount Due. Payment Applied is only
    the part of each cheque used on this invoice; the whole cheque and what is
    left of it are in the payments table, and the leftover also prints as
    Credit Remaining under the Amount Due. #}
{%- set amount_due = doc.outstanding_amount if doc.docstatus == 1 else (order_total - (doc.total_advance or 0)) %}

{#- Header details: the Sales Order(s) the invoice came from, its Delivery
    Location (Sales Invoice has no field for it) and the customer's phone. #}
{%- set sales_orders = doc.items | map(attribute="sales_order") | select | unique | list %}
{%- set location = namespace(name="") %}
{%- for so in sales_orders %}{% if not location.name %}
  {%- set loc = frappe.db.get_value("Sales Order", so, "custom_pick_up_location") %}
  {%- if loc %}{% set location.name = frappe.db.get_value("Pick-Up Location", loc, "location_name") or loc %}{% endif %}
{%- endif %}{% endfor %}
{#- Phone: the customer's current numbers from the Phone Numbers grid on the
    Customer (primary first); the invoice's own contact fields are usually
    blank because the contact carries no "primary mobile". #}
{%- set phones = frappe.get_all("Customer Phone Entry", filters={"parent": doc.customer, "parenttype": "Customer", "parentfield": "custom_phone_numbers", "custom_current": 1}, fields=["phone"], order_by="is_primary_phone desc, idx asc") | map(attribute="phone") | select | list %}
{%- set phone = phones | join(" / ") or doc.contact_mobile or doc.contact_phone or "" %}

{#- Payments received: advances pulled into the invoice plus payments made
    against it after submit, each once. Check # is the cheque number; a payment
    made any other way shows its mode (Cash, …).
    For each one: Amount = the whole cheque, Applied = the part used on this
    invoice, Credit = what is left of the cheque after this invoice and the
    invoices made before it (e.g. paid for a whole order, invoiced in part —
    the rest stays as credit on the order, and the backorder invoice shows
    only that rest). #}
{%- set pay = namespace(seen=[], paid=0, applied=0, credit=0) %}
{%- set payments = [] %}
{#- A share still to come keeps its deposit on the order, so its cheque may be
    applied only in part, or not at all, here: list it anyway. #}
{%- for adv in doc.advances %}{% if adv.allocated_amount or view.held %}
  {%- set _ = payments.append({"type": adv.reference_type, "name": adv.reference_name, "applied": adv.allocated_amount, "available": adv.advance_amount}) %}
  {%- set _ = pay.seen.append(adv.reference_name) %}
{%- endif %}{% endfor %}
{%- if doc.docstatus == 1 %}
  {%- for ref in frappe.get_all("Payment Entry Reference", filters={"reference_doctype": "Sales Invoice", "reference_name": doc.name, "docstatus": 1}, fields=["parent", "allocated_amount"]) %}
    {%- if ref.parent not in pay.seen %}
      {%- set _ = payments.append({"type": "Payment Entry", "name": ref.parent, "applied": ref.allocated_amount, "available": ref.allocated_amount}) %}
      {%- set _ = pay.seen.append(ref.parent) %}
    {%- endif %}
  {%- endfor %}
{%- endif %}
{#- The order's other invoices made before this one (not cancelled, not returns). #}
{%- set earlier = [["docstatus", "<", 2], ["is_return", "=", 0], ["name", "!=", doc.name or ""]] + ([["creation", "<", doc.creation]] if doc.creation else []) %}
{%- for p in payments %}
  {%- set pe = frappe.db.get_value(p.type, p.name, "name") %}
  {%- if not pe %}{% set _ = p.update({"missing": 1, "paid": 0, "credit": 0, "check": p.name, "date": None}) %}
  {%- elif p.type == "Payment Entry" %}
    {%- set pe = frappe.db.get_value("Payment Entry", p.name, ["mode_of_payment", "reference_no", "reference_date", "posting_date", "paid_amount"], as_dict=1) %}
    {#- Used on the order's EARLIER invoices (created before this one, draft or
        submitted; this one excluded, it is p.applied). A backorder invoice
        then shows only what the first invoice left of the cheque, or 0.
        Drafts count because every invoice is a draft until it is submitted:
        the cheque's own references only know submitted ones. A submitted
        invoice has both an advance row and a reference row for the same
        money, so per invoice the larger of the two is taken, not the sum. #}
    {%- set used = {} %}
    {%- for a in frappe.get_all("Sales Invoice", filters=earlier + [["Sales Invoice Advance", "reference_name", "=", p.name]], fields=["name", "`tabSales Invoice Advance`.allocated_amount as allocated"]) %}
      {%- set _ = used.update({a.name: (used.get(a.name) or 0) + a.allocated}) %}
    {%- endfor %}
    {%- set by_ref = {} %}
    {%- for r in frappe.get_all("Payment Entry Reference", filters={"parent": p.name, "reference_doctype": "Sales Invoice", "reference_name": ["!=", doc.name], "docstatus": 1}, fields=["reference_name", "allocated_amount"]) %}
      {%- set _ = by_ref.update({r.reference_name: (by_ref.get(r.reference_name) or 0) + r.allocated_amount}) %}
    {%- endfor %}
    {%- if by_ref %}
      {%- for inv in frappe.get_all("Sales Invoice", filters=earlier + [["name", "in", by_ref.keys() | list]], pluck="name") %}
        {%- set _ = used.update({inv: [used.get(inv) or 0, by_ref[inv]] | max}) %}
      {%- endfor %}
    {%- endif %}
    {%- set other = used.values() | sum %}
    {%- set _ = p.update({"paid": pe.paid_amount, "credit": [pe.paid_amount - other - p.applied, 0] | max}) %}
  {%- else %}
    {%- set pe = frappe.db.get_value("Journal Entry", p.name, ["cheque_no as reference_no", "cheque_date as reference_date", "posting_date"], as_dict=1) %}
    {#- A journal's advance amount already leaves out what submitted invoices
        took; earlier DRAFT invoices still have to come off. #}
    {%- set other = frappe.get_all("Sales Invoice", filters=earlier + [["docstatus", "=", 0], ["Sales Invoice Advance", "reference_name", "=", p.name]], fields=["`tabSales Invoice Advance`.allocated_amount as allocated"]) | sum(attribute="allocated") %}
    {%- set _ = p.update({"paid": p.available, "credit": [p.available - other - p.applied, 0] | max}) %}
  {%- endif %}
  {%- if not p.missing %}{% set _ = p.update({"check": pe.reference_no or pe.mode_of_payment or "", "date": pe.reference_date or pe.posting_date}) %}{% endif %}
  {%- set pay.paid = pay.paid + p.paid %}
  {%- set pay.applied = pay.applied + p.applied %}
  {%- set pay.credit = pay.credit + p.credit %}
{%- endfor %}
{#- What is left of the payments: the deposit of a share still to come is held
    for that share's invoice, only the rest is free credit. #}
{%- set share_held = ([view.held_deposit, pay.credit] | min) if view.held else 0 %}
{%- set free_credit = pay.credit - share_held %}

<style>
  .ls-inv { font-family: Helvetica, Arial, sans-serif; font-size: 10pt; color: #000; }
  .ls-inv table { width: 100%; border-collapse: collapse; }
  .ls-inv td { vertical-align: top; }
  .ls-inv .title { text-align: center; font-size: 20pt; font-weight: 700; padding-bottom: 4px; }
  .ls-inv .meta td { padding: 1px 0; }
  .ls-inv .lbl { font-weight: 700; }
  .ls-inv .num { text-align: right; white-space: nowrap; }
  /* #10 window envelope, letter folded in thirds: the window shows roughly
     2"-3" from the top of the sheet and 7/8"-5 3/8" from the left. With 15 mm
     page margins the address block starts ~1.4" / ~0.3" into the content, and
     Ship To starts right of the window (left column = 68% of 7.3"). */
  .ls-inv .top { height: 1.4in; }
  .ls-inv .window { height: 1.05in; width: 3.4in; padding-left: 0.3in; font-size: 11pt; line-height: 1.3; }
  .ls-inv .items { margin-top: 14px; }
  .ls-inv .items th, .ls-inv .items td { border: 1px solid #c8ccd0; padding: 4px 8px; }
  .ls-inv .items th { text-align: left; font-weight: 700; vertical-align: bottom; color: #000; }
  .ls-inv .items th.num { text-align: right; }
  .ls-inv .sub { color: #555; font-size: 8pt; }
  .ls-inv .totals td { padding: 1px 0 4px 0; }
  .ls-inv .totals td.lbl { text-align: right; padding-right: 6px; }
  .ls-inv .pay { margin-top: 14px; page-break-inside: avoid; }
  .ls-inv .pay th, .ls-inv .pay td { border: 1px solid #c8ccd0; padding: 4px 8px; text-align: left; color: #000; }
  .ls-inv .pay .num { text-align: right; }
  .ls-inv .share-head td { font-weight: 700; background: #f4f5f6; }
  .ls-inv .share-line td:first-child { padding-left: 18px; }
  .ls-inv .share-bal td { font-weight: 700; border-top: 1.5px solid #333; }
  .ls-inv .held th { background: #f4f5f6; }
  .ls-inv .note { font-size: 9pt; color: #333; }
  .ls-inv .thanks { text-align: center; font-size: 15pt; font-weight: 700; margin-top: 22px; page-break-inside: avoid; }
  .ls-inv .farm { text-align: center; font-weight: 700; margin-top: 8px; }
</style>

<div class="ls-inv">

  <div class="top">
    <div class="title">LS Foods</div>
    <table class="meta">
      <tr>
        <td style="width:60%"></td>
        <td class="num">
          <div><span class="lbl">{{ _("Credit Note") if doc.is_return else _("Invoice") }}:</span> {{ doc.name }}</div>
          <div><span class="lbl">{{ _("Date") }}:</span> {{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>
          {%- if sales_orders %}
          <div><span class="lbl">{{ _("Order ID") }}:</span> {{ sales_orders | join(", ") }}</div>
          {%- endif %}
          {%- if doc.po_no %}<div><span class="lbl">{{ _("PO") }}:</span> {{ doc.po_no }}</div>{% endif %}
        </td>
      </tr>
    </table>
  </div>

  <table>
    <tr>
      <td style="width:68%">
        <div class="window">
          <div class="lbl">{{ _("Bill To") }}</div>
          <div style="font-weight:700">{{ doc.customer_name }}</div>
          {%- if doc.address_display %}<div>{{ doc.address_display }}</div>{% endif %}
          {%- if phone %}<div>{{ phone }}</div>{% endif %}
        </div>
      </td>
      <td style="width:32%">
        {%- set ship_to = doc.shipping_address or doc.address_display %}
        {%- if ship_to %}
        <div class="lbl">{{ _("Ship To") }}</div>
        <div>{{ doc.shipping_address_name and frappe.db.get_value("Address", doc.shipping_address_name, "address_title") or doc.customer_name }}</div>
        <div>{{ ship_to }}</div>
        {%- endif %}
      </td>
    </tr>
  </table>

  <table class="meta" style="margin-top:6px">
    {%- set project_name = doc.project and frappe.db.get_value("Project", doc.project, "project_name") %}
    {%- if project_name %}
    <tr>
      <td><span class="lbl">{{ _("Project") }}:</span> {{ project_name }}</td>
    </tr>
    {%- endif %}
    <tr>
      <td>{% if location.name %}<span class="lbl">{{ _("Delivery Location") }}:</span> {{ location.name }}{% endif %}</td>
    </tr>
  </table>

  {%- if view.shares %}
  <table class="items">
    <thead>
      <tr>
        <th>{{ _("Beef / Hog Share") }}</th>
        <th class="num" style="width:62px">{{ _("Qty") }}</th>
        <th style="width:56px">{{ _("Unit") }}</th>
        <th class="num" style="width:74px">{{ _("Price") }}</th>
        <th class="num" style="width:90px">{{ _("Item Total") }}</th>
      </tr>
    </thead>
    <tbody>
      {%- for s in view.shares %}
      <tr class="share-head">
        <td>{{ s.row.item_name }} ({{ frappe.format(s.weight, {"fieldtype": "Float"}) }} lbs.)</td>
        <td class="num">{{ frappe.format(s.row.qty, {"fieldtype": "Float"}) }}</td>
        <td></td>
        <td></td>
        <td class="num">{{ frappe.format_value(s.subtotal, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- if s.deposit %}
      <tr class="share-line">
        <td>{{ _(s.deposit_label) }}</td>
        <td class="num">{{ frappe.format(s.deposit_units, {"fieldtype": "Float"}) }}</td>
        <td></td>
        <td class="num">-{{ frappe.format_value(s.deposit_each, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">-{{ frappe.format_value(s.deposit, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endif %}
      <tr class="share-line">
        <td>{{ s.row.item_name }} &mdash; {{ _("hanging weight") }}</td>
        <td class="num">{{ frappe.format(s.weight, {"fieldtype": "Float"}) }}</td>
        <td>{{ _("Pounds") }}</td>
        <td class="num">{{ frappe.format_value(s.row.custom_unit_price, {"fieldtype": "Currency"}, doc) }}<span class="sub"> /lb</span></td>
        <td class="num">{{ frappe.format_value(s.row.amount, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- if s.fee %}
      <tr class="share-line">
        <td>{{ s.fee.item_name }}</td>
        {#- Qty and rate are typed from the processor's bill — print them as entered, in the line's own unit. #}
        <td class="num">{{ frappe.format(s.fee.qty, {"fieldtype": "Float"}) }}</td>
        <td>{{ s.fee.uom }}</td>
        <td class="num">{{ frappe.format_value(s.fee.rate, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">{{ frappe.format_value(s.fee.amount, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endif %}
      <tr class="share-bal">
        <td colspan="4">{{ _("Balance due for this share") }}</td>
        <td class="num">{{ frappe.format_value(s.balance, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>
  {%- endif %}

  {%- if products %}
  <table class="items">
    <thead>
      <tr>
        <th style="width:84px">{{ _("Product Code") }}</th>
        <th>{{ _("Description") }}</th>
        <th class="num" style="width:70px">{{ _("Quantity") }}</th>
        <th class="num" style="width:74px">{{ _("Price") }}</th>
        <th class="num" style="width:82px">{{ _("Item Total") }}</th>
      </tr>
    </thead>
    <tbody>
      {%- for row in products %}
      <tr>
        <td>{{ row.item_code }}</td>
        <td>
          {{ row.item_name }}
          {#- Priced by the pound: the weight is what sets the price, so show it. #}
          {%- if row.custom_unit_price and row.custom_case_weight and is_priced_per_lb(row.item_code, doc.customer, doc.posting_date) %}
          <div class="sub">{{ frappe.format(row.custom_case_weight, {"fieldtype": "Float"}) }} lb @ {{ frappe.format_value(row.custom_unit_price, {"fieldtype": "Currency"}, doc) }}/lb</div>
          {%- endif %}
        </td>
        <td class="num">{{ frappe.format(row.qty, {"fieldtype": "Float"}) }}</td>
        <td class="num">{{ frappe.format_value(row.rate, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">{{ frappe.format_value(row.amount, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>
  {%- endif %}

  {%- if view.held %}
  <table class="items held">
    <thead>
      <tr>
        <th>{{ _("Beef / Hog Share — invoiced later") }}</th>
        <th class="num" style="width:70px">{{ _("Quantity") }}</th>
        <th class="num" style="width:96px">{{ _("Deposit") }}</th>
      </tr>
    </thead>
    <tbody>
      {%- for h in view.held %}
      <tr>
        <td>{{ h.item_name }}<div class="sub">{{ h.item_code }}</div></td>
        <td class="num">{{ frappe.format(h.qty, {"fieldtype": "Float"}) }}</td>
        <td class="num">{{ frappe.format_value(h.deposit, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endfor %}
      <tr>
        <td colspan="3" class="note">
          {{ _("Not part of this invoice. The share is invoiced on its own once the hanging weight is known: hanging weight x price per lb, plus processing, less the deposit.") }}
        </td>
      </tr>
    </tbody>
  </table>
  {%- endif %}

  <table style="margin-top:14px">
    <tr>
      <td style="width:55%">
        {%- if t.grains or t.pollock or doc.terms %}
        <div>
          <span class="lbl">{{ _("Order Notes") }}:</span>
          {%- if t.grains %}
          We recommend storing all grains in temperatures below 55 degrees to prevent bugs and
          weevils. Use containers with tight lids. We offer Gamma lids for 5-gallon buckets. If an
          infestation occurs, freeze the grains for a week and store below 40 degrees. Organic
          grains may be more susceptible.
          {%- endif %}
          {%- if t.pollock %}
          {%- if t.grains %}<br><br>{% endif %}
          We recommend repackaging the pollock in freezer bags to prevent freezer burn.
          {%- endif %}
          {%- if doc.terms %}{% if t.grains or t.pollock %}<br><br>{% endif %}{{ doc.terms }}{% endif %}
        </div>
        {%- endif %}

      </td>
      <td style="width:45%">
        <table class="totals">
          {%- if t.has_free %}
          <tr><td class="lbl">{{ _("Free Dairy/Pizza") }}:</td><td class="num" style="width:90px">-{{ frappe.format_value(-t.free, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}
          <tr><td class="lbl">{{ _("Subtotal") }}:</td><td class="num" style="width:90px">{{ frappe.format_value(subtotal, {"fieldtype": "Currency"}, doc) }}</td></tr>
          <tr><td class="lbl">{{ _("Delivery Charge") }}:</td><td class="num">{{ frappe.format_value(t.delivery, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- if t.has_late %}
          <tr><td class="lbl">{{ _("Late Order Charge") }}:</td><td class="num">{{ frappe.format_value(t.late, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}
          {%- for tax in doc.taxes %}{% if tax.tax_amount %}
          <tr><td class="lbl">{{ tax.description }}:</td><td class="num">{{ frappe.format_value(tax.tax_amount, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}{% endfor %}
          {%- if doc.discount_amount %}
          <tr><td class="lbl">{{ _("Discount") }}:</td><td class="num">-{{ frappe.format_value(doc.discount_amount, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}
          <tr><td class="lbl">{{ _("Total") }}:</td><td class="num">{{ frappe.format_value(order_total, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- if not doc.is_return %}
          <tr><td class="lbl">{{ _("Payment Applied") }}:</td><td class="num">{{ frappe.format_value(order_total - amount_due, {"fieldtype": "Currency"}, doc) }}</td></tr>
          <tr><td class="lbl">{{ _("Total Amount Due") }}:</td><td class="num" style="font-weight:700">{{ frappe.format_value(amount_due, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- if share_held > 0.005 %}
          <tr><td class="lbl">{{ _("Beef / Hog Share Deposit (held)") }}:</td><td class="num">{{ frappe.format_value(share_held, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}
          {%- if free_credit > 0.005 %}
          <tr><td class="lbl">{{ _("Credit Remaining") }}:</td><td class="num">{{ frappe.format_value(free_credit, {"fieldtype": "Currency"}, doc) }}</td></tr>
          {%- endif %}
          {%- endif %}
        </table>
      </td>
    </tr>
  </table>

  {%- if payments %}
  <table class="pay">
    <tr>
      <th>{{ _("Check #") }}</th><th>{{ _("Date") }}</th><th class="num">{{ _("Amount Paid") }}</th>
      <th class="num">{{ _("Applied to Invoice") }}</th><th class="num">{{ _("Credit Remaining") }}</th>
    </tr>
    {%- for p in payments %}
    <tr>
      <td>{{ p.check }}</td>
      <td>{{ frappe.format(p.date, {"fieldtype": "Date"}) }}</td>
      <td class="num">{{ frappe.format_value(p.paid, {"fieldtype": "Currency"}, doc) }}</td>
      <td class="num">{{ frappe.format_value(p.applied, {"fieldtype": "Currency"}, doc) }}</td>
      <td class="num">{{ frappe.format_value(p.credit, {"fieldtype": "Currency"}, doc) }}</td>
    </tr>
    {%- endfor %}
    {%- if payments | length > 1 %}
    <tr style="font-weight:700">
      <td colspan="2">{{ _("Total") }}</td>
      <td class="num">{{ frappe.format_value(pay.paid, {"fieldtype": "Currency"}, doc) }}</td>
      <td class="num">{{ frappe.format_value(pay.applied, {"fieldtype": "Currency"}, doc) }}</td>
      <td class="num">{{ frappe.format_value(pay.credit, {"fieldtype": "Currency"}, doc) }}</td>
    </tr>
    {%- endif %}
  </table>
  {%- if share_held > 0.005 %}
  <div class="note" style="margin-top:4px">
    {{ _("Of the credit remaining, {0} is the deposit for your beef / hog share; it comes off the share's invoice.").format(frappe.format_value(share_held, {"fieldtype": "Currency"}, doc)) }}
  </div>
  {%- endif %}
  {%- endif %}

  <div class="thanks">Thank you for supporting small farms and local business!</div>
  <div class="farm">52941 York Hills Dr. Middlebury IN 46540 -- 574-971-4424</div>
</div>

{# LS Foods — "Earnings Statement" Salary Slip print format.
   Pixel-matched to the ADP-style US pay stub. Fully dynamic off the Salary Slip,
   its linked Employee, Company and Company Address. Target: ERPNext v15 / wkhtmltopdf.
   Layout uses tables + floats (no flexbox/grid) so it renders identically in wkhtmltopdf. #}

{%- set emp = frappe.get_doc("Employee", doc.employee) -%}
{%- set comp = frappe.get_doc("Company", doc.company) -%}
{%- set addr_name = frappe.db.get_value("Dynamic Link",
        {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") -%}
{%- set addr = frappe.get_doc("Address", addr_name) if addr_name else None -%}

{%- macro money(v) -%}{{ "{:,.2f}".format(v | float) }}{%- endmacro -%}
{%- set ssn = (emp.get("custom_social_security_number") or "") | string -%}

<style>
  .es-wrap { font-family: Helvetica, Arial, sans-serif; color: #1a1a1a; font-size: 13px;
             width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .es-wrap table { border-collapse: collapse; width: 100%; }
  .es-wrap td, .es-wrap th { vertical-align: top; }

  /* ---- top header ---- */
  .es-title      { font-size: 27px; font-weight: bold; letter-spacing: .2px; line-height: 1.1; }
  .es-sub        { color: #333; line-height: 1.55; }
  .es-right      { text-align: right; }
  .es-meta       { color: #333; line-height: 1.6; }

  /* ---- coloured bands ---- */
  .es-band-emp   { background-color: #dfe6f8; padding: 10px 22px; margin-top: 12px; }
  .es-band-tot   { background-color: #d5dff5; }
  .es-name       { font-weight: bold; font-size: 14px; text-align: right; }

  /* ---- section tables ---- */
  .es-section    { margin-top: 16px; }
  .es-rule       { border-top: 1px solid #9a9a9a; }
  .es-head td    { font-weight: bold; padding: 5px 14px 7px; border-bottom: 1px solid #9a9a9a; }
  .es-row td     { padding: 6px 14px; }
  .es-grey       { background-color: #f2f2f2; }
  .es-c          { text-align: center; }
  .es-r          { text-align: right; }
  .es-totrow td  { padding: 8px 14px; font-weight: bold; }

  /* ---- cut line ---- */
  .es-cut        { margin: 16px 0 4px; color: #888; }
  .es-dash       { border-top: 1px dashed #9a9a9a; height: 0; margin-top: 8px; }

  /* ---- check stub ---- */
  .es-stub       { margin-top: 14px; }
  .es-stub .es-sub { line-height: 1.5; }
  .es-words      { background-color: #dfe6f8; }
  .es-words td   { padding: 11px 18px; font-weight: bold; vertical-align: middle; }
  .es-amtbox     { background-color: #2c4a94; color: #ffffff; text-align: right;
                   font-weight: bold; font-size: 16px; width: 200px; }
  .es-sign       { margin-top: 24px; }
  .es-signline   { border-top: 1px solid #555; width: 300px; float: right; text-align: left;
                   padding-top: 4px; color: #333; }
</style>

<div class="es-wrap">

  {# ============================= HEADER ============================= #}
  <table>
    <tr>
      <td style="width: 58%;">
        <div class="es-title">{{ doc.company }}</div>
        <div class="es-sub" style="margin-top: 8px;">
          {% if addr %}{{ addr.address_line1 }}{% if addr.city %} {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %}{% if addr.pincode %} {{ addr.pincode }}{% endif %}<br>{% endif %}
          {% if addr and addr.phone %}{{ addr.phone }}<br>{% endif %}
          EIN: {{ comp.tax_id or "" }}
        </div>
      </td>
      <td class="es-right" style="width: 42%;">
        <div class="es-title">Earnings Statement</div>
        <div class="es-meta" style="margin-top: 8px;">
          Period Ending: {{ frappe.utils.formatdate(doc.end_date, "MM/dd/yyyy") }}<br>
          Pay Date: {{ frappe.utils.formatdate(doc.posting_date, "MM/dd/yyyy") }}
        </div>
      </td>
    </tr>
  </table>

  {# ========================= EMPLOYEE BAND ========================= #}
  <div class="es-band-emp">
    <table>
      <tr>
        <td style="width: 60%; line-height: 1.55;">
          <b>SSN:</b>{{ emp.custom_social_security_number or "" }}<br>
          <b>Taxable Marital Status:</b> {{ emp.marital_status or "" }}<br>
          <b>Exemptions/Allowances:</b> {{ emp.get("custom_exemptions_allowances") or 0 }}
        </td>
        <td class="es-name" style="width: 40%;">{{ doc.employee_name }}</td>
      </tr>
    </table>
  </div>

  {# ============================ EARNINGS ============================ #}
  <div class="es-section">
    <table>
      <tr class="es-head">
        <td style="width: 26%;">Earnings</td>
        <td class="es-c" style="width: 15%;">Rate</td>
        <td class="es-c" style="width: 15%;">Hours</td>
        <td class="es-r" style="width: 22%;">This Period</td>
        <td class="es-r" style="width: 22%;">Year to Date</td>
      </tr>
      {%- for row in doc.earnings %}
      {%- set c = row.salary_component | lower -%}
      {%- set is_wage = ('wage' in c) or ('hourly' in c) or ('regular' in c) or ('salary' in c) -%}
      <tr class="es-row">
        <td class="es-grey">{{ row.salary_component }}</td>
        <td class="es-c">{% if is_wage and emp.get("custom_rate_per_hour") %}{{ money(emp.custom_rate_per_hour) }}{% endif %}</td>
        <td class="es-c">{% if is_wage and doc.custom_hours_worked %}{{ money(doc.custom_hours_worked) }}{% endif %}</td>
        <td class="es-r">{{ money(row.amount) }}</td>
        <td class="es-r">{{ money(row.year_to_date) }}</td>
      </tr>
      {%- endfor %}
      {# short grey filler to mirror the stub's empty earnings block #}
      <tr><td class="es-grey" style="height: 44px;"></td><td colspan="4"></td></tr>
    </table>
    <table class="es-band-tot es-totrow">
      <tr>
        <td style="width: 26%;">Gross Pay</td>
        <td style="width: 30%;"></td>
        <td class="es-r" style="width: 22%;">${{ money(doc.gross_pay) }}</td>
        <td class="es-r" style="width: 22%;">${{ money(doc.gross_year_to_date) }}</td>
      </tr>
    </table>
  </div>

  {# =========================== DEDUCTIONS =========================== #}
  <div class="es-section">
    <table>
      <tr class="es-head">
        <td style="width: 22%;">Deductions</td>
        <td class="es-c" style="width: 30%;">Type</td>
        <td class="es-r" style="width: 24%;">This Period</td>
        <td class="es-r" style="width: 24%;">Year to Date</td>
      </tr>
      {%- for row in doc.deductions %}
      <tr class="es-row">
        <td></td>
        <td class="es-grey">{{ row.salary_component }}</td>
        <td class="es-r">{{ money(row.amount) }}</td>
        <td class="es-r">{{ money(row.year_to_date) }}</td>
      </tr>
      {%- endfor %}

      {#
        Expense reimbursements. These are NOT wages: the employee is being paid
        back money they already spent, so the amount is excluded from Gross Pay
        and from every tax calculation, then added to Net Pay after deductions.
        Showing it here is what makes the stub arithmetic legible —
        Gross - Deductions + Reimbursements = Net Pay.
      #}
      {%- if doc.custom_total_reimbursement %}
      <tr><td colspan="4" style="height: 10px;"></td></tr>
      <tr class="es-head">
        <td style="width: 22%;">Reimbursements</td>
        <td class="es-c" style="width: 30%;">Expense Claim</td>
        <td class="es-r" style="width: 24%;">This Period</td>
        <td class="es-r" style="width: 24%;">Not Taxable</td>
      </tr>
      {%- for row in doc.custom_reimbursements %}
      <tr class="es-row">
        <td></td>
        <td class="es-grey">{{ row.expense_type or row.expense_claim }}</td>
        <td class="es-r">{{ money(row.amount) }}</td>
        <td class="es-r"></td>
      </tr>
      {%- endfor %}
      {%- endif %}
    </table>
    <table class="es-band-tot es-totrow">
      <tr>
        <td style="width: 22%;">Net Pay</td>
        <td style="width: 30%;"></td>
        <td class="es-r" style="width: 24%;">${{ money(doc.net_pay) }}</td>
        <td class="es-r" style="width: 24%;">${{ money(doc.year_to_date) }}</td>
      </tr>
    </table>
  </div>

  <div style="margin-top: 24px; font-weight: bold;">
    Your deductions for this period are ${{ money(doc.total_deduction) }}
    {%- if doc.custom_total_reimbursement %},
    and you were reimbursed ${{ money(doc.custom_total_reimbursement) }} for expenses
    {%- endif %}
  </div>

  {# ============================= CUT LINE ============================= #}
  <div class="es-cut">
    <span style="font-size: 15px;">&#9986;</span>
    <div class="es-dash"></div>
  </div>

  {# ============================ CHECK STUB ============================ #}
  <div class="es-stub">
    <table>
      <tr>
        <td style="width: 60%;">
          <div class="es-sub">
            {{ doc.company }}<br>
            {% if addr %}{{ addr.address_line1 }}{% if addr.city %} {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %}{% if addr.pincode %} {{ addr.pincode }}{% endif %}{% endif %}
          </div>
        </td>
        <td class="es-meta" style="width: 40%;">
          Payroll Check Number: {{ doc.bank_account_no or "" }}<br>
          Pay Date: {{ frappe.utils.formatdate(doc.posting_date, "MM/dd/yyyy") }}
        </td>
      </tr>
    </table>

    <div style="font-weight: bold; margin: 18px 0 14px;">{{ doc.employee_name }}</div>

    <table class="es-words">
      <tr>
        <td>
          {%- set words = (doc.custom_total_in_words or doc.total_in_words or "") -%}
          {%- set words = words.replace("USD", "").replace("only.", "").replace("only", "").strip() -%}
          {{ words }}
        </td>
        <td class="es-amtbox">${{ money(doc.net_pay) }}</td>
      </tr>
    </table>

    <div class="es-sign">
      <div class="es-signline">Authorized Signature</div>
      <div style="clear: both;"></div>
    </div>
  </div>

</div>
